import pandas as pd
import numpy as np

# Load the bike-share data into a pandas DataFrame
data = pd.read_csv('chunks_csv/cyclehire_w002.csv')

# Load the borough adjacency list into a pandas DataFrame
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute the Self-Containment Ratio for each borough
data['StartBorough'] = data['StartBorough'].str.upper()
data['EndBorough'] = data['EndBorough'].str.upper()
data['SelfContained'] = (data['StartBorough'] == data['EndBorough']).astype(int)
data['Departures'] = data.groupby('StartBorough')['StartBorough'].transform('count')
data['SelfContainedTrips'] = data.groupby('StartBorough')['SelfContained'].transform('sum')
data['SelfContainmentRatio'] = data['SelfContainedTrips'] / data['Departures']

# Create a list of neighboring boroughs for each borough
adjacency_list = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in adjacency_list:
        adjacency_list[row['borough']] = []
    if row['neighbor'] not in adjacency_list:
        adjacency_list[row['neighbor']] = []
    adjacency_list[row['borough']].append(row['neighbor'])
    adjacency_list[row['neighbor']].append(row['borough'])

# Identify hot spots and cold spots
hot_spots = []
cold_spots = []
for index, row in data.iterrows():
    if row['SelfContainmentRatio'] > 0.8 and all(data['SelfContainmentRatio'] > 0.8 for neighbor in adjacency_list[row['StartBorough']]):
        hot_spots.append((row['StartBorough'], row['SelfContainmentRatio']))
    elif row['SelfContainmentRatio'] < 0.2 and all(data['SelfContainmentRatio'] < 0.2 for neighbor in adjacency_list[row['StartBorough']]):
        cold_spots.append((row['StartBorough'], row['SelfContainmentRatio']))

# Perform a permutation test to determine the statistical significance of the hot spots and cold spots
np.random.seed(0)
p_values = {}
for _ in range(500):
    data_perm = data.copy()
    data_perm['SelfContainmentRatio'] = np.random.permutation(data_perm['SelfContainmentRatio'])
    for index, row in data_perm.iterrows():
        if row['StartBorough'] in p_values:
            p_values[row['StartBorough']].append(row['SelfContainmentRatio'])
        else:
            p_values[row['StartBorough']] = [row['SelfContainmentRatio']]

# Identify the boroughs that meet the criteria for hot spots or cold spots based on the p-values and Self-Containment Ratios
for borough, ratio in hot_spots:
    p_value = np.mean([x > ratio for x in p_values.get(borough, [])])
    if p_value < 0.05:
        print(f"FINAL ANSWER: {borough} (HH, statistical method={p_value})")
for borough, ratio in cold_spots:
    p_value = np.mean([x < ratio for x in p_values.get(borough, [])])
    if p_value < 0.05:
        print(f"FINAL ANSWER: {borough} (LL, statistical method={p_value})")

# Print the number of data points used in the final calculation
data_points_used = data['SelfContainmentRatio'].count()
print(f"data_points_used = {data_points_used}")

import pandas as pd
import numpy as np

# Load the bike-share data
bike_data = pd.read_csv('chunks_csv/cyclehire_w002.csv')

# Load the borough adjacency list
adjacency_list = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute the Self-Containment Ratio for each borough
boroughs = bike_data['StartBorough'].unique()
self_containment_ratios = {}
for borough in boroughs:
    departures = bike_data[bike_data['StartBorough'] == borough].shape[0]
    self_contained_trips = bike_data[(bike_data['StartBorough'] == borough) & (bike_data['EndBorough'] == borough)].shape[0]
    self_containment_ratios[borough] = self_contained_trips / departures if departures > 0 else 0

# Create a list of neighboring boroughs for each borough
neighborhoods = {}
for index, row in adjacency_list.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Identify hot spots and cold spots
hot_spots = []
cold_spots = []
for borough, ratio in self_containment_ratios.items():
    if ratio > 0.8:
        neighbors = [neighbor for neighbor in neighborhoods[borough] if neighbor in self_containment_ratios]
        if all(ratio > 0.8 for neighbor in neighbors):
            hot_spots.append((borough, ratio))
    elif ratio < 0.2:
        neighbors = [neighbor for neighbor in neighborhoods[borough] if neighbor in self_containment_ratios]
        if all(ratio < 0.2 for neighbor in neighbors):
            cold_spots.append((borough, ratio))

# Perform a permutation test to determine the statistical significance of the hot spots and cold spots
num_permutations = 500
p_values = {}
for borough, ratio in self_containment_ratios.items():
    null_distribution = np.random.permutation(list(self_containment_ratios.values()))
    num_higher = sum(1 for permuted_ratio in null_distribution if permuted_ratio > ratio)
    p_values[borough] = 1 - (num_higher + 1) / (num_permutations + 1)

# Identify the boroughs that meet the criteria for hot spots or cold spots based on the p-values and Self-Containment Ratios
significant_hot_spots = [(borough, ratio, p_value) for borough, ratio, p_value in zip([b[0] for b in hot_spots], [b[1] for b in hot_spots], [p_values[b[0]] for b in hot_spots]) if p_value < 0.05]
significant_cold_spots = [(borough, ratio, p_value) for borough, ratio, p_value in zip([b[0] for b in cold_spots], [b[1] for b in cold_spots], [p_values[b[0]] for b in cold_spots]) if p_value < 0.05]

# Print the results
data_points_used = len(self_containment_ratios)
print(f'data_points_used = {data_points_used}')
if significant_hot_spots:
    print(f'FINAL ANSWER: {", ".join([f"{borough} (HH, test statistic={ratio}, significance measure={p_value})" for borough, ratio, p_value in significant_hot_spots])}')
elif significant_cold_spots:
    print(f'FINAL ANSWER: {", ".join([f"{borough} (LL, test statistic={ratio}, significance measure={p_value})" for borough, ratio, p_value in significant_cold_spots])}')
else:
    print('FINAL ANSWER: none')
